export interface ConnectorConfig {
  intercomAccessToken: string
  zendeskAccessToken: string
  zendeskSubdomain: string
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  topic: string
  data: {
    item: {
      type: string
      id: string
      subject: string
      tags: {
        type: string
        tags: Array<{
          type: string
          id: string
          name: string
        }>
      }
    }
  }
}

export interface IntercomConversationResponse {
  conversation_message: {
    body: string
    subject: string
  }
  tags: {
    type: string
    tags: Array<{
      type: string
      id: string
      name: string
      applied_at: number
      applied_by: {
        type: string
        id: string
      }
    }>
  }
  updated_at: number
}

export interface ZendeskTicketResponse {
  ticket: {
    id: number
    subject: string
    comment: {
      body: string
    }
  }
}

export interface HandleResult {
  intercomConversationId: string
  zendeskTicketId: number
}

async function fetchWithRetry(
  fetch: typeof fetch,
  url: string,
  init: RequestInit,
  maxRetries = 3,
  baseMs = 1000,
): Promise<Response> {
  let lastResponse: Response
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const response = await fetch(url, init)
    lastResponse = response
    if (response.status < 400 || response.status === 401 || response.status === 403 || response.status === 404) {
      return response
    }
    if (attempt === maxRetries) break
    const retryAfter = response.headers.get('retry-after')
    let delayMs: number
    if (retryAfter) {
      const parsed = parseInt(retryAfter, 10)
      if (!Number.isNaN(parsed)) {
        delayMs = parsed * 1000
      } else {
        const date = new Date(retryAfter)
        if (!Number.isNaN(date.getTime())) {
          delayMs = Math.max(0, date.getTime() - Date.now())
        } else {
          delayMs = baseMs * 2 ** attempt
        }
      }
    } else {
      delayMs = baseMs * 2 ** attempt
    }
    if (delayMs > 0 && Number.isFinite(delayMs)) {
      await new Promise((resolve) => setTimeout(resolve, delayMs))
    }
  }
  return lastResponse!
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetch = config.fetch ?? globalThis.fetch
  if (!fetch) throw new Error('fetch is not available')

  if (!payload.topic) throw new Error('Missing required field: topic')
  if (payload.topic !== 'conversation.tag.created') {
    throw new Error(`Unsupported topic: ${payload.topic}`)
  }
  if (!payload.data?.item) throw new Error('Missing required field: data.item')
  const conversation = payload.data.item
  if (conversation.type !== 'conversation') throw new Error('Item type is not conversation')
  if (!conversation.id) throw new Error('Missing required field: conversation.id')
  if (!conversation.subject) throw new Error('Missing required field: conversation.subject')
  if (!conversation.tags?.tags?.length) throw new Error('Missing required field: conversation.tags.tags')

  const hasRefundTag = conversation.tags.tags.some((tag) => tag.name === 'refund')
  if (!hasRefundTag) {
    throw new Error('Conversation does not have the "refund" tag')
  }

  const intercomUrl = `https://api.intercom.io/conversations/${conversation.id}`
  const intercomResponse = await fetchWithRetry(fetch, intercomUrl, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.intercomAccessToken}`,
      Accept: 'application/json',
    },
  })

  if (intercomResponse.status !== 200) {
    throw new Error(`Intercom API error: ${intercomResponse.status} ${intercomResponse.statusText} for GET ${intercomUrl}`)
  }

  const intercomData = (await intercomResponse.json()) as IntercomConversationResponse

  const conversationUrl = `https://app.intercom.com/conversations/${conversation.id}`
  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`
  const zendeskBody = {
    ticket: {
      subject: intercomData.conversation_message.subject || conversation.subject,
      comment: {
        body: `Conversation link: ${conversationUrl}`,
      },
    },
  }

  const zendeskResponse = await fetchWithRetry(fetch, zendeskUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.zendeskAccessToken}`,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify(zendeskBody),
  })

  if (zendeskResponse.status !== 201 && zendeskResponse.status !== 200) {
    throw new Error(`Zendesk API error: ${zendeskResponse.status} ${zendeskResponse.statusText} for POST ${zendeskUrl}`)
  }

  const zendeskData = (await zendeskResponse.json()) as ZendeskTicketResponse

  return {
    intercomConversationId: conversation.id,
    zendeskTicketId: zendeskData.ticket.id,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, IntercomWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      intercomAccessToken: 'test-intercom-token',
      zendeskAccessToken: 'test-zendesk-token',
      zendeskSubdomain: 'testsubdomain',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.intercomConversationId).toBe('12345')
    expect(result.zendeskTicketId).toBe(123)
  })
})

describe('handle', () => {
  it('creates Zendesk ticket with conversation link on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.intercom.io/conversations/12345' && req.method === 'GET') {
        return jsonResponse(TARGET_ENDPOINTS[0].response)
      }
      if (req.url === 'https://testsubdomain.zendesk.com/api/v2/tickets.json' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[1].response, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'intercom-token',
      zendeskAccessToken: 'zendesk-token',
      zendeskSubdomain: 'testsubdomain',
      fetch,
    }

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '12345',
          subject: 'Refund request',
          tags: {
            type: 'tag.list',
            tags: [{ type: 'tag', id: 'tag_refund', name: 'refund' }],
          },
        },
      },
    }

    const result = await handle(payload, config)

    expect(result.intercomConversationId).toBe('12345')
    expect(result.zendeskTicketId).toBe(123)
    expect(calls).toHaveLength(2)

    expect(calls[0].method).toBe('GET')
    expect(calls[0].url).toBe('https://api.intercom.io/conversations/12345')
    expect(calls[0].headers.get('authorization')).toBe('Bearer intercom-token')

    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toBe('https://testsubdomain.zendesk.com/api/v2/tickets.json')
    expect(calls[1].headers.get('authorization')).toBe('Bearer zendesk-token')
    expect(calls[1].json).toEqual({
      ticket: {
        subject: 'Refund request',
        comment: { body: 'Conversation link: https://app.intercom.com/conversations/12345' },
      },
    })
  })

  it('throws when topic is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      intercomAccessToken: 't',
      zendeskAccessToken: 't',
      zendeskSubdomain: 't',
      fetch,
    }
    const payload = { data: { item: { type: 'conversation', id: '1', subject: 's', tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund' }] } } } } as unknown as IntercomWebhookPayload
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: topic')
  })

  it('throws when conversation.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      intercomAccessToken: 't',
      zendeskAccessToken: 't',
      zendeskSubdomain: 't',
      fetch,
    }
    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '', subject: 's', tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund' }] } } },
    }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: conversation.id')
  })

  it('throws when conversation.subject is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      intercomAccessToken: 't',
      zendeskAccessToken: 't',
      zendeskSubdomain: 't',
      fetch,
    }
    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '1', subject: '', tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund' }] } } },
    }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: conversation.subject')
  })

  it('throws when refund tag is not present', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      intercomAccessToken: 't',
      zendeskAccessToken: 't',
      zendeskSubdomain: 't',
      fetch,
    }
    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '1', subject: 's', tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'other' }] } } },
    }
    await expect(handle(payload, config)).rejects.toThrow('Conversation does not have the "refund" tag')
  })

  it('throws on non-2xx Intercom response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'not found' }, 404))
    const config: ConnectorConfig = {
      intercomAccessToken: 't',
      zendeskAccessToken: 't',
      zendeskSubdomain: 't',
      fetch,
    }
    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '1', subject: 's', tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund' }] } } },
    }
    await expect(handle(payload, config)).rejects.toThrow('Intercom API error: 404 Not Found for GET https://api.intercom.io/conversations/1')
    expect(calls).toHaveLength(1)
  })

  it('throws on non-2xx Zendesk response', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.intercom.io/conversations/1' && req.method === 'GET') {
        return jsonResponse(TARGET_ENDPOINTS[0].response)
      }
      return jsonResponse({ error: 'unauthorized' }, 401)
    })
    const config: ConnectorConfig = {
      intercomAccessToken: 't',
      zendeskAccessToken: 't',
      zendeskSubdomain: 't',
      fetch,
    }
    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '1', subject: 's', tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund' }] } } },
    }
    await expect(handle(payload, config)).rejects.toThrow('Zendesk API error: 401 Unauthorized for POST https://t.zendesk.com/api/v2/tickets.json')
    expect(calls).toHaveLength(2)
  })

  it('retries on 429 and succeeds', async () => {
    let attempt = 0
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.intercom.io/conversations/1' && req.method === 'GET') {
        if (attempt === 0) {
          attempt++
          return jsonResponse({ error: 'rate limited' }, 429)
        }
        return jsonResponse(TARGET_ENDPOINTS[0].response)
      }
      if (req.url === 'https://test.zendesk.com/api/v2/tickets.json' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[1].response, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 't',
      zendeskAccessToken: 't',
      zendeskSubdomain: 'test',
      fetch,
    }
    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '1', subject: 's', tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund' }] } } },
    }

    vi.useFakeTimers()
    const promise = handle(payload, config)
    await vi.runAllTimersAsync()
    const result = await promise

    expect(result.zendeskTicketId).toBe(123)
    expect(calls.filter((c) => c.url === 'https://api.intercom.io/conversations/1')).toHaveLength(2)
    vi.useRealTimers()
  })

  it('exhausts retries on persistent 429', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'rate limited' }, 429))
    const config: ConnectorConfig = {
      intercomAccessToken: 't',
      zendeskAccessToken: 't',
      zendeskSubdomain: 't',
      fetch,
    }
    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '1', subject: 's', tags: { type: 'tag.list', tags: [{ type: 'tag', id: '1', name: 'refund' }] } } },
    }

    vi.useFakeTimers()
    const promise = handle(payload, config)
    await vi.runAllTimersAsync()
    await expect(promise).rejects.toThrow('Intercom API error: 429 Too Many Requests')
    expect(calls.filter((c) => c.url === 'https://api.intercom.io/conversations/1')).toHaveLength(4)
    vi.useRealTimers()
  })
})

