async function fetchWithRetry(
  fetch: FetchFn,
  url: string,
  init: RequestInit,
  maxRetries = 3,
  baseMs = 1000,
): Promise<Response> {
  let lastResponse: Response
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const response = await fetch(url, init)
    lastResponse = response
    if (response.status < 400 || response.status === 401 || response.status === 403 || response.status === 404) {
      return response
    }
    if (attempt === maxRetries) break
    const retryAfter = response.headers.get('retry-after')
    let delayMs: number
    if (retryAfter) {
      const parsed = parseInt(retryAfter, 10)
      if (!Number.isNaN(parsed)) {
        delayMs = parsed * 1000
      } else {
        const date = new Date(retryAfter)
        if (!Number.isNaN(date.getTime())) {
          delayMs = Math.max(0, date.getTime() - Date.now())
        } else {
          delayMs = baseMs * 2 ** attempt
        }
      }
    } else {
      delayMs = baseMs * 2 ** attempt
    }
    if (delayMs > 0 && Number.isFinite(delayMs)) {
      await new Promise((resolve) => setTimeout(resolve, delayMs))
    }
  }
  return lastResponse!
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetch = config.fetch ?? globalThis.fetch
  if (!fetch) throw new Error('fetch is not available')

  if (!payload.topic) throw new Error('Missing required field: topic')
  if (payload.topic !== 'conversation.tag.created') {
    throw new Error(`Unsupported topic: ${payload.topic}`)
  }
  if (!payload.data?.item) throw new Error('Missing required field: data.item')
  const conversation = payload.data.item
  if (conversation.type !== 'conversation') throw new Error('Item type is not conversation')
  if (!conversation.id) throw new Error('Missing required field: conversation.id')
  if (!conversation.subject) throw new Error('Missing required field: conversation.subject')
  if (!conversation.tags?.tags?.length) throw new Error('Missing required field: conversation.tags.tags')

  const hasRefundTag = conversation.tags.tags.some((tag) => tag.name === 'refund')
  if (!hasRefundTag) {
    throw new Error('Conversation does not have the "refund" tag')
  }

  const intercomUrl = `https://api.intercom.io/conversations/${conversation.id}`
  const intercomResponse = await fetchWithRetry(fetch, intercomUrl, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.intercomAccessToken}`,
      Accept: 'application/json',
    },
  })

  if (intercomResponse.status !== 200) {
    throw new Error(`Intercom API error: ${intercomResponse.status} ${intercomResponse.statusText} for GET ${intercomUrl}`)
  }

  const intercomData = (await intercomResponse.json()) as IntercomConversationResponse

  const conversationUrl = `https://app.intercom.com/conversations/${conversation.id}`
  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`
  const zendeskBody = {
    ticket: {
      subject: intercomData.conversation_message.subject || conversation.subject,
      comment: {
        body: `Conversation link: ${conversationUrl}`,
      },
    },
  }

  const zendeskResponse = await fetchWithRetry(fetch, zendeskUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.zendeskAccessToken}`,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify(zendeskBody),
  })

  if (zendeskResponse.status !== 201 && zendeskResponse.status !== 200) {
    throw new Error(`Zendesk API error: ${zendeskResponse.status} ${zendeskResponse.statusText} for POST ${zendeskUrl}`)
  }

  const zendeskData = (await zendeskResponse.json()) as ZendeskTicketResponse

  return {
    intercomConversationId: conversation.id,
    zendeskTicketId: zendeskData.ticket.id,
  }
}

